/**
 * Binary Search
 * Time: O(log n) | Space: O(1)
 * 
 * Finds the index of a target value in a sorted array.
 * Returns -1 if not found.
 */

function binarySearch(arr, target) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);

    if (arr[mid] === target) return mid;
    if (arr[mid] < target) left = mid + 1;
    else right = mid - 1;
  }

  return -1;
}

// --- Examples ---
console.log(binarySearch([1, 3, 5, 7, 9, 11], 7));  // 3
console.log(binarySearch([1, 3, 5, 7, 9, 11], 4));  // -1

// --- Variation: First occurrence ---
function binarySearchFirst(arr, target) {
  let left = 0, right = arr.length - 1, result = -1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (arr[mid] === target) { result = mid; right = mid - 1; }
    else if (arr[mid] < target) left = mid + 1;
    else right = mid - 1;
  }
  return result;
}

module.exports = { binarySearch, binarySearchFirst };

/**
 * Merge Sort
 * Time: O(n log n) | Space: O(n)
 * 
 * Stable sort that divides the array in half recursively,
 * then merges sorted halves back together.
 */

function mergeSort(arr) {
  if (arr.length <= 1) return arr;

  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));

  return merge(left, right);
}

function merge(left, right) {
  const result = [];
  let i = 0, j = 0;

  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i++]);
    } else {
      result.push(right[j++]);
    }
  }

  return [...result, ...left.slice(i), ...right.slice(j)];
}

// --- Example ---
const arr = [38, 27, 43, 3, 9, 82, 10];
console.log(mergeSort(arr)); // [3, 9, 10, 27, 38, 43, 82]

module.exports = { mergeSort };

/**
 * Breadth-First Search (BFS) — Graph Traversal
 * Time: O(V + E) | Space: O(V)
 * 
 * Explores all vertices at the current depth before moving deeper.
 * Useful for shortest path in unweighted graphs.
 */

function bfs(graph, start) {
  const visited = new Set();
  const queue = [start];
  const result = [];

  visited.add(start);

  while (queue.length > 0) {
    const vertex = queue.shift();
    result.push(vertex);

    for (const neighbor of graph[vertex] || []) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
      }
    }
  }

  return result;
}

// --- Example ---
const graph = {
  A: ['B', 'C'],
  B: ['A', 'D', 'E'],
  C: ['A', 'F'],
  D: ['B'],
  E: ['B', 'F'],
  F: ['C', 'E'],
};

console.log(bfs(graph, 'A')); // ['A', 'B', 'C', 'D', 'E', 'F']

module.exports = { bfs };

/**
 * Fibonacci — Multiple Approaches
 * Demonstrates memoization, tabulation, and space-optimized DP.
 */

// 1. Recursive with Memoization — O(n) time, O(n) space
function fibMemo(n, memo = {}) {
  if (n in memo) return memo[n];
  if (n <= 1) return n;
  memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  return memo[n];
}

// 2. Bottom-Up Tabulation — O(n) time, O(n) space
function fibTab(n) {
  if (n <= 1) return n;
  const dp = new Array(n + 1);
  dp[0] = 0;
  dp[1] = 1;
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }
  return dp[n];
}

// 3. Space Optimized — O(n) time, O(1) space
function fibOptimized(n) {
  if (n <= 1) return n;
  let prev2 = 0, prev1 = 1;
  for (let i = 2; i <= n; i++) {
    const curr = prev1 + prev2;
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}

// --- Examples ---
console.log(fibMemo(10));      // 55
console.log(fibTab(10));       // 55
console.log(fibOptimized(10)); // 55
console.log(fibOptimized(50)); // 12586269025

module.exports = { fibMemo, fibTab, fibOptimized };

"""
Longest Common Subsequence (LCS)
Time: O(m * n) | Space: O(m * n)

Finds the longest subsequence common to two strings.
Classic dynamic programming problem.
"""

def lcs(text1, text2):
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

def lcs_string(text1, text2):
    """Returns the actual LCS string, not just the length."""
    m, n = len(text1), len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack to find the string
    result = []
    i, j = m, n
    while i > 0 and j > 0:
        if text1[i - 1] == text2[j - 1]:
            result.append(text1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(result))

# --- Examples ---
if __name__ == '__main__':
    print(lcs('abcde', 'ace'))              # 3
    print(lcs_string('abcde', 'ace'))        # 'ace'
    print(lcs_string('AGGTAB', 'GXTXAYB'))  # 'GTAB'

/**
 * Binary Tree Traversals — Inorder, Preorder, Postorder, Level-Order
 * Time: O(n) for all | Space: O(h) for recursive, O(n) for level-order
 */

class TreeNode {
  constructor(val, left = null, right = null) {
    this.val = val;
    this.left = left;
    this.right = right;
  }
}

// Inorder: Left → Root → Right (gives sorted order for BST)
function inorder(root) {
  const result = [];
  function traverse(node) {
    if (!node) return;
    traverse(node.left);
    result.push(node.val);
    traverse(node.right);
  }
  traverse(root);
  return result;
}

// Preorder: Root → Left → Right
function preorder(root) {
  const result = [];
  function traverse(node) {
    if (!node) return;
    result.push(node.val);
    traverse(node.left);
    traverse(node.right);
  }
  traverse(root);
  return result;
}

// Postorder: Left → Right → Root
function postorder(root) {
  const result = [];
  function traverse(node) {
    if (!node) return;
    traverse(node.left);
    traverse(node.right);
    result.push(node.val);
  }
  traverse(root);
  return result;
}

// Level-Order (BFS)
function levelOrder(root) {
  if (!root) return [];
  const result = [];
  const queue = [root];
  while (queue.length > 0) {
    const level = [];
    const size = queue.length;
    for (let i = 0; i < size; i++) {
      const node = queue.shift();
      level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(level);
  }
  return result;
}

// --- Example ---
const tree = new TreeNode(1,
  new TreeNode(2, new TreeNode(4), new TreeNode(5)),
  new TreeNode(3, null, new TreeNode(6))
);

console.log('Inorder:', inorder(tree));       // [4, 2, 5, 1, 3, 6]
console.log('Preorder:', preorder(tree));     // [1, 2, 4, 5, 3, 6]
console.log('Postorder:', postorder(tree));   // [4, 5, 2, 6, 3, 1]
console.log('Level-Order:', levelOrder(tree)); // [[1], [2,3], [4,5,6]]

module.exports = { TreeNode, inorder, preorder, postorder, levelOrder };
